using System.Reflection;
using System.Runtime.Loader;
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using Microsoft.CodeAnalysis.Testing;

namespace Receipts.GeneratedTests;

public class Req2129ContractlessReferencedTypeTests
{
    private const string ProjectASource = """
        namespace ProjectA
        {
            public class MyType
            {
                public int Value { get; set; }
                public string Name { get; set; }
            }
        }
        """;

    private const string ProjectBSource = """
        using MessagePack;
        using MessagePack.Formatters;

        namespace ProjectB
        {
            [GeneratedMessagePackFormatter]
            public partial class MyTypeFormatter : IMessagePackFormatter<ProjectA.MyType>;

            [GeneratedMessagePackResolver]
            partial class ReceiptResolver { }
        }
        """;

    [Fact]
    public async Task BodylessFormatterForReferencedTypeIsGeneratedAndCompiles()
    {
        (Assembly projectA, Assembly projectB) = await BuildAsync(ProjectASource, projectAReferencesMessagePack: false, ProjectBSource);

        Assert.DoesNotContain(projectA.GetReferencedAssemblies(), a => a.Name is string n && n.StartsWith("MessagePack", StringComparison.Ordinal));
        Type formatterType = projectB.GetType("ProjectB.MyTypeFormatter", throwOnError: true)!;
        Type myType = projectA.GetType("ProjectA.MyType", throwOnError: true)!;
        Type formatterInterface = typeof(global::MessagePack.Formatters.IMessagePackFormatter<>).MakeGenericType(myType);
        Assert.True(formatterInterface.IsAssignableFrom(formatterType));
    }

    [Fact]
    public async Task ContractlessFormatterRoundTripsPublicMembers()
    {
        (Assembly projectA, Assembly projectB) = await BuildAsync(ProjectASource, projectAReferencesMessagePack: false, ProjectBSource);

        Type myType = projectA.GetType("ProjectA.MyType", throwOnError: true)!;
        object instance = Activator.CreateInstance(myType)!;
        myType.GetProperty("Value")!.SetValue(instance, 5);
        myType.GetProperty("Name")!.SetValue(instance, "x");

        global::MessagePack.MessagePackSerializerOptions options = OptionsWith(projectB, "ProjectB.MyTypeFormatter");
        byte[] bytes = global::MessagePack.MessagePackSerializer.Serialize(myType, instance, options);
        string json = global::MessagePack.MessagePackSerializer.ConvertToJson(new ReadOnlyMemory<byte>(bytes));

        Assert.StartsWith("{", json);
        Assert.Contains("\"Name\":\"x\"", json);
        Assert.Contains("\"Value\":5", json);

        object? back = global::MessagePack.MessagePackSerializer.Deserialize(myType, new ReadOnlyMemory<byte>(bytes), options);
        Assert.NotNull(back);
        Assert.Equal(5, myType.GetProperty("Value")!.GetValue(back));
        Assert.Equal("x", myType.GetProperty("Name")!.GetValue(back));
    }

    private static global::MessagePack.MessagePackSerializerOptions OptionsWith(Assembly projectB, string formatterTypeName)
    {
        Type formatterType = projectB.GetType(formatterTypeName, throwOnError: true)!;
        var formatter = (global::MessagePack.Formatters.IMessagePackFormatter)Activator.CreateInstance(formatterType)!;
        var resolver = global::MessagePack.Resolvers.CompositeResolver.Create(
            new[] { formatter },
            new global::MessagePack.IFormatterResolver[] { global::MessagePack.Resolvers.StandardResolver.Instance });
        return global::MessagePack.MessagePackSerializerOptions.Standard.WithResolver(resolver);
    }

    private static MetadataReference[] MessagePackReferences() => new MetadataReference[]
    {
        MetadataReference.CreateFromFile(typeof(global::MessagePack.MessagePackSerializer).Assembly.Location),
        MetadataReference.CreateFromFile(typeof(global::MessagePack.KeyAttribute).Assembly.Location),
    };

    private static byte[] EmitOrFail(Compilation compilation)
    {
        using MemoryStream stream = new();
        var result = compilation.Emit(stream);
        Assert.True(result.Success, string.Join(Environment.NewLine, result.Diagnostics.Where(d => d.Severity == DiagnosticSeverity.Error)));
        return stream.ToArray();
    }

    private static async Task<(Assembly ProjectA, Assembly ProjectB)> BuildAsync(string sourceA, bool projectAReferencesMessagePack, string sourceB)
    {
        ImmutableArray<MetadataReference> framework = await ReferenceAssemblies.Net.Net80.ResolveAsync(LanguageNames.CSharp, CancellationToken.None);
        CSharpParseOptions parseOptions = new(LanguageVersion.CSharp12);
        CSharpCompilationOptions compilationOptions = new(OutputKind.DynamicallyLinkedLibrary);

        List<MetadataReference> referencesA = new(framework);
        if (projectAReferencesMessagePack)
        {
            referencesA.AddRange(MessagePackReferences());
        }

        CSharpCompilation compilationA = CSharpCompilation.Create("ProjectA", new[] { CSharpSyntaxTree.ParseText(sourceA, parseOptions) }, referencesA, compilationOptions);
        byte[] imageA = EmitOrFail(compilationA);

        List<MetadataReference> referencesB = new(framework);
        referencesB.AddRange(MessagePackReferences());
        referencesB.Add(MetadataReference.CreateFromImage(imageA.ToImmutableArray()));
        CSharpCompilation compilationB = CSharpCompilation.Create("ProjectB", new[] { CSharpSyntaxTree.ParseText(sourceB, parseOptions) }, referencesB, compilationOptions);

        GeneratorDriver driver = CSharpGeneratorDriver.Create(
            new[] { new global::MessagePack.SourceGenerator.MessagePackGenerator().AsSourceGenerator() },
            parseOptions: parseOptions);
        driver = driver.RunGeneratorsAndUpdateCompilation(compilationB, out Compilation output, out ImmutableArray<Diagnostic> generatorDiagnostics);
        Assert.Empty(generatorDiagnostics.Where(d => d.Severity == DiagnosticSeverity.Error));
        Assert.All(driver.GetRunResult().Results, r => Assert.Null(r.Exception));

        byte[] imageB = EmitOrFail(output);
        ReceiptLoadContext context = new();
        Assembly assemblyA = context.Add(imageA);
        Assembly assemblyB = context.Add(imageB);
        return (assemblyA, assemblyB);
    }

    private sealed class ReceiptLoadContext : AssemblyLoadContext
    {
        private readonly Dictionary<string, Assembly> loaded = new(StringComparer.Ordinal);

        public ReceiptLoadContext()
            : base("Req2129Contractless-" + Guid.NewGuid().ToString("N"))
        {
        }

        public Assembly Add(byte[] image)
        {
            Assembly assembly = this.LoadFromStream(new MemoryStream(image));
            this.loaded[assembly.GetName().Name!] = assembly;
            return assembly;
        }

        protected override Assembly? Load(AssemblyName assemblyName)
        {
            return assemblyName.Name is string name && this.loaded.TryGetValue(name, out Assembly? assembly) ? assembly : null;
        }
    }
}

